static class NativeApp {
 [DllImport("user32.dll",CharSet=CharSet.Unicode)] static extern IntPtr FindWindow(string cls,string title);
 [DllImport("user32.dll")] static extern bool SetForegroundWindow(IntPtr hwnd);
 [DllImport("user32.dll")] static extern bool ShowWindow(IntPtr hwnd,int cmd);
 [STAThread] static void Main(string[] args){if(args.Length==2&&args[0]=="--snapshot-demo")Environment.SetEnvironmentVariable("CHRONOS_NATIVE_DEMO","1");Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var mutex=new System.Threading.Mutex(false,"Local\\ChronosAgentNativeUI"+(Environment.GetEnvironmentVariable("CHRONOS_NATIVE_DEMO")=="1"?".Demo":""))){if(!mutex.WaitOne(0,false)){var window=FindWindow(null,"Chronos Agent · 电脑采集器");ShowWindow(window,9);SetForegroundWindow(window);return;}if(args.Length==2&&args[0]=="--snapshot-demo"&&Environment.GetEnvironmentVariable("CHRONOS_NATIVE_DEMO")=="1"){using(var form=new ControlWindow()){form.Show();var until=DateTime.UtcNow.AddSeconds(2);while(DateTime.UtcNow<until){Application.DoEvents();System.Threading.Thread.Sleep(10);}using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save(args[1],System.Drawing.Imaging.ImageFormat.Png);}form.Close();}}else Application.Run(new ControlWindow());}}
}
sealed class AgentSkin {
 public Color Ink,Muted,Surface,Background,Accent,Gradient,Line,G1,G2,G3; public bool Dark,Industrial,Colorful;
 public static Color C(string s){return ColorTranslator.FromHtml(s);}
 public AgentSkin(){
  Dark=false;Industrial=false;Colorful=true;
  Ink=C("#233044");Muted=C("#59667A");Surface=Color.White;Background=C("#F1F5F8");
  Accent=C("#4C5F9E");G1=C("#D5ECE1");G2=C("#E2DAF4");G3=C("#F1D6CB");
  Gradient=Blend(Surface,Accent,.12f);Line=C("#D2D9E3");
 }
 public Color CardTint(int index){var c=index%3==0?G1:index%3==1?G2:G3;return Blend(Surface,c,Colorful?(Dark?.48f:.7f):.3f);}
 public static Color Blend(Color a,Color b,float t){return Color.FromArgb((int)(a.R+(b.R-a.R)*t),(int)(a.G+(b.G-a.G)*t),(int)(a.B+(b.B-a.B)*t));}
 public static GraphicsPath Round(Rectangle r,int radius){var p=new GraphicsPath();int d=Math.Max(2,radius*2);p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
}
sealed class GlassPanel:Panel {
 public AgentSkin Skin;public int Tint;
 public GlassPanel(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;Padding=new Padding(12);}
 protected override void OnPaintBackground(PaintEventArgs e){base.OnPaintBackground(e);if(Skin==null)return;var r=new Rectangle(1,1,Width-3,Height-3);if(r.Width<10||r.Height<10)return;e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var path=AgentSkin.Round(r,Skin.Industrial?5:20))using(var b=new LinearGradientBrush(r,Skin.CardTint(Tint),AgentSkin.Blend(Skin.Surface,Skin.CardTint(Tint+1),.2f),35f))using(var line=new Pen(Skin.Line)){e.Graphics.FillPath(b,path);e.Graphics.DrawPath(line,path);}}
}

