 protected override void OnPaintBackground(PaintEventArgs e){var r=ClientRectangle;if(r.Width<1||r.Height<1)return;using(var b=new LinearGradientBrush(r,skin.G1,skin.G3,35f)){b.InterpolationColors=new ColorBlend{Colors=new[]{skin.G1,skin.G2,skin.G3},Positions=new[]{0f,.55f,1f}};e.Graphics.FillRectangle(b,r);}}
 void ScaleForDpi(){float dpi;using(var g=CreateGraphics())dpi=g.DpiX/96f;var work=Screen.FromControl(this).WorkingArea;float f=Math.Min(dpi,Math.Min((work.Width-40)/760f,(work.Height-70)/640f));Scale(new SizeF(f,f));ClientSize=new Size((int)(760*f),(int)(640*f));}
 Label Heading(string text,float size,bool bold){return new Label{Text=text,AutoSize=true,Font=new Font(Font.FontFamily,size,bold?FontStyle.Bold:FontStyle.Regular),BackColor=Color.Transparent,ForeColor=size<=9?skin.Muted:skin.Ink,Margin=new Padding(0,0,0,5)};}
